import { execFileSync } from 'node:child_process'
import { mkdir, readdir, readFile, writeFile, lstat, symlink, realpath, unlink } from 'node:fs/promises'
import { dirname, join, relative, resolve, isAbsolute } from 'node:path'
import { root, contract } from './paths.mjs'

// DSH's pinned manifests resolve lib/ paths. Compatibility junctions retain
// those contracts while every generated byte lives under artifacts/dev.
const tracked = new Set(execFileSync('git', ['ls-files', '--recurse-submodules'], { cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 ** 2 }).split(/\r?\n/))
async function walk(directory) {
  const result = []
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (!entry.isDirectory() || ['node_modules', '.git', 'lib', 'dist', 'artifacts', 'out'].includes(entry.name)) continue
    result.push(...await walk(join(directory, entry.name)))
  }
  try { result.push({ directory, manifest: JSON.parse(await readFile(join(directory, 'package.json'), 'utf8')) }) } catch (e) { if (e.code !== 'ENOENT') throw e }
  return result
}
let count = 0
for (const { directory, manifest } of await walk(root)) {
  if (manifest?.name === undefined) continue
  const packageOutput = join(contract.dev, manifest.name.replaceAll('/', '__'))
  await mkdir(packageOutput, { recursive: true })
  await writeFile(join(packageOutput, '.source.json'), JSON.stringify({ source: directory }))
  if (!await lstat(join(packageOutput, 'package.json')).catch(() => undefined)) {
    await symlink(join(directory, 'package.json'), join(packageOutput, 'package.json'), 'file')
  }
  const sharedDependency = join(contract.dev, 'node_modules', manifest.name)
  await mkdir(dirname(sharedDependency), { recursive: true })
  if (!await lstat(sharedDependency).catch(() => undefined)) await symlink(directory, sharedDependency, process.platform === 'win32' ? 'junction' : 'dir')
  // The pinned client bundler consumes tsc maps relative to the physical
  // output. Expose source for reading without generating anything there.
  const sourceDirectory = join(directory, 'src')
  const sourceAlias = join(packageOutput, 'src')
  if (await lstat(sourceDirectory).catch(() => undefined) && !await lstat(sourceAlias).catch(() => undefined)) {
    await symlink(sourceDirectory, sourceAlias, process.platform === 'win32' ? 'junction' : 'dir')
  }
  const dependencyRoot = join(directory, 'node_modules')
  if (await lstat(dependencyRoot).catch(() => undefined)) {
    const dependencyLink = join(packageOutput, 'node_modules')
    const oldLink = await lstat(dependencyLink).catch(() => undefined)
    // Only withdraw the compatibility link created by this script. No
    // installed node_modules tree is moved, recursively deleted or rewritten.
    if (oldLink?.isSymbolicLink()) {
      if (await realpath(dependencyLink) !== await realpath(dependencyRoot)) throw new Error('Unknown output dependency link')
      await unlink(dependencyLink)
    }
    await mirrorDependencies(dependencyRoot, dependencyLink)
  }
  if (manifest.name === '@daweifu/capability-menu') continue
  const outputs = manifest.name === '@zerowallscience/desktop' ? ['out'] : ['lib', ...(manifest.name === '@deepseek-ai/dsh-web-frontend' || /(?:vite|build|bundle)/.test(manifest.scripts?.build ?? '') ? ['dist'] : [])]
  for (const output of outputs) {
    const link = join(directory, output)
    const prefix = relative(root, link).replaceAll('\\', '/') + '/'
    if ([...tracked].some(path => path.startsWith(prefix))) continue
    const target = join(contract.dev, manifest.name.replaceAll('/', '__'), output)
    await mkdir(target, { recursive: true })
    const existing = await lstat(link).catch(e => { if (e.code !== 'ENOENT') throw e })
    if (existing) {
      if (!existing.isSymbolicLink() || await realpath(link) !== await realpath(target)) throw new Error(`Output ${link} already exists outside the artifact contract; preserve it and explicitly relocate before building.`)
    } else await symlink(target, link, process.platform === 'win32' ? 'junction' : 'dir')
    count++
  }
}
console.log(`Bound ${count} compatibility output paths to ${contract.dev}`)

// Aggregate caches live outside package lib directories in the fixed DSH tree.
// Redirect only these known, untracked cache files, retaining their bytes.
for (const file of ['tsconfig.host.tsbuildinfo', 'tsconfig.client.tsbuildinfo']) {
  const source = join(root, 'deepseek-harness', file)
  if (tracked.has(`deepseek-harness/${file}`)) throw new Error('Refusing to relocate a tracked DSH file')
  const target = join(contract.cache, 'dsh', 'typescript', file)
  const contained = relative(contract.artifacts, target)
  if (contained.startsWith('..') || isAbsolute(contained)) throw new Error('Cache target is outside artifacts')
  await mkdir(dirname(target), { recursive: true })
  const existing = await lstat(source).catch(() => undefined)
  if (existing?.isSymbolicLink()) {
    if (await realpath(source) !== await realpath(target)) throw new Error('Unknown TypeScript cache link')
    continue
  }
  if (existing) {
    await writeFile(target, await readFile(source))
    await unlink(source)
  } else if (!await lstat(target).catch(() => undefined)) await writeFile(target, '')
  await symlink(target, source, 'file')
}

async function mirrorDependencies(source, destination) {
  await mkdir(destination, { recursive: true })
  for (const entry of await readdir(source, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue
    const target = join(destination, entry.name)
    const original = join(source, entry.name)
    if (entry.name.startsWith('@') && entry.isDirectory()) { await mirrorDependencies(original, target); continue }
    if (!await lstat(target).catch(() => undefined)) {
      const physical = await realpath(original).catch(() => undefined)
      if (physical) await symlink(physical, target, process.platform === 'win32' ? 'junction' : 'dir')
    }
  }
}
